inline bool AsciiEqual(std::string_view a, std::string_view b) {
  if (a.size() != b.size()) return false;
  for (size_t i = 0; i < a.size(); ++i) {
    const auto lower = [](unsigned char c) {
      return c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c;
    };
    if (lower(a[i]) != lower(b[i])) return false;
  }
  return true;
}
inline bool ShardFontHidden(std::string_view name, uint32_t seed) {
  if (name.empty() || !seed) return false;
  for (const auto allowed : kProtectedFontNames)
    if (AsciiEqual(name, allowed)) return false;
  return FontHash(name, seed) % 1000u < 30u;
}
