inline uint32_t WindowsFontCohortV1(uint32_t seed) {
  return (seed ^ (seed >> 16)) & 3u;
}
inline bool ShardWindowsFontHiddenV1(std::string_view name, uint32_t seed) {
  if (name.empty() || !seed) return false;
  for (const auto core : kProtectedFontNames)
    if (AsciiEqual(name, core)) return false;
  for (const auto core : kWindowsBaseFontNamesV1)
    if (AsciiEqual(name, core)) return false;
  const auto cohort = WindowsFontCohortV1(seed);
  for (const auto supplemental : kWindowsSupplementalFontNamesV1)
    if (AsciiEqual(name, supplemental)) return (cohort & 1u) == 0;
  // One observed application-font installation is kept or hidden together.
  // This avoids inventing thousands of partial Office/designer font sets.
  return (cohort & 2u) == 0;
}

